import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import InputPassword from './InputPassword';

describe('InputPassword', () => {
  test('should render', () => {
    render(<InputPassword data-testid="input-password" />);
    const input = screen.getByTestId('input-password');
    fireEvent.change(input, { target: { value: 'abc' } });
    const showButton = screen.getByText('Show');
    fireEvent.click(showButton);
    expect(input.type).toBe('text');
    const hideButton = screen.getByText('Hide');
    fireEvent.click(hideButton);
    expect(input.type).toBe('password');
  });

  test('should render when controlled', () => {
    let mockValue = '';
    const mockOnChange = jest.fn();
    mockOnChange.mockImplementation((event) => {
      mockValue = event.target.value;
    });

    const { rerender } = render(
      <InputPassword value={mockValue} onChange={mockOnChange} data-testid="input-password" />
    );
    const input = screen.getByTestId('input-password');
    fireEvent.change(input, { target: { value: 'abc' } });
    expect(mockOnChange).toHaveBeenCalledTimes(1);
    rerender(
      <InputPassword value={mockValue} onChange={mockOnChange} data-testid="input-password" />
    );
    expect(input.value).toBe('abc');
  });

  test('should change the value when onChange is passed as prop', () => {
    const mockOnChange = jest.fn();
    render(<InputPassword onChange={mockOnChange} data-testid="input-password" />);
    const input = screen.getByTestId('input-password');
    fireEvent.change(input, { target: { value: 'abc' } });
    expect(mockOnChange).toHaveBeenCalledTimes(1);
    expect(input.value).toBe('abc');
  });

  test('should render with error', () => {
    render(<InputPassword data-testid="input-password" hasError size="medium" />);
    expect(screen.getByTestId('input-password')).toBeInTheDocument();
  });

  test('should render with default value', () => {
    render(<InputPassword data-testid="input-password" defaultValue="abc123" />);
    const input = screen.getByTestId('input-password');
    expect(input.value).toBe('abc123');
  });
});
